<?php declare(strict_types=1);namespace StudPulse\Integrations;use StudPulse\Database\DB;use StudPulse\Http\ApiError;final class DriveLibraryTree{public static function path(array$root,string$folder):?array{$path=[];$seen=[];while($folder!==$root['folder_id']){if(isset($seen[$folder]))return null;$seen[$folder]=true;$row=DB::one('SELECT remote_id AS id,parent_id,name,restricted FROM drive_sync_folders WHERE root_id=? AND remote_id=?',[$root['id'],$folder]);if(!$row||$row['restricted'])return null;$path[]=['id'=>$row['id'],'name'=>$row['name']];$folder=$row['parent_id'];}$path[]=['id'=>$folder,'name'=>$root['folder_name']];return array_reverse($path);}public static function listing(array$root,string$folder):array{$path=self::path($root,$folder)??throw new ApiError(404,'DRIVE_FOLDER_MISSING','Папка не найдена в библиотеке группы.');$items=DB::all('SELECT remote_id AS id,name FROM drive_sync_folders
            WHERE root_id=? AND parent_id=? AND restricted=0 ORDER BY name,remote_id',[$root['id'],$folder]);return['path'=>$path,'items'=>$items];}public static function remember(array$root,array$folder,?string$scan):void{$id=DriveSync::id($folder['id']);$parent=DriveSync::id($folder['parents'][0]??null);$restricted=DB::one("SELECT 1 FROM google_drive_folders WHERE user_id=? AND account_key=?
            AND drive_id=? AND folder_key LIKE 'teacher:%' LIMIT 1",[$root['user_id'],$root['account_key'],$id]);DB::run('INSERT INTO drive_sync_folders(root_id,remote_id,parent_id,name,restricted,scan_id) VALUES(?,?,?,?,?,?)
            AS incoming ON DUPLICATE KEY UPDATE parent_id=incoming.parent_id,name=incoming.name,restricted=incoming.restricted,
            scan_id=COALESCE(incoming.scan_id,drive_sync_folders.scan_id)',[$root['id'],$id,$parent,$folder['name'],(int)(bool)$restricted,$scan]);}}